import platform
import socket
import sys


def perform(input, context):
    total = sum(input["numbers"])

    print(f"Hello {input['name']} from Python {platform.python_version()} on {platform.system()}/{platform.machine()}")

    return {
        "greeting": f"Hello, {input['name']}!",
        "total": total,
        "runtime": {
            "python": platform.python_version(),
            "platform": platform.system(),
            "arch": platform.machine(),
            "hostname": socket.gethostname(),
        },
    }
